<?php
declare(strict_types=1); require_once __DIR__.'/../includes/functions.php'; require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/returns.php');verify_csrf();$id=(int)post('id');$pdo=db();try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM rentals WHERE id=? AND status='borrowed' FOR UPDATE");$s->execute([$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('รายการนี้ถูกคืนแล้วหรือไม่พบข้อมูล');$fine=fine_amount($r['due_date']);$pdo->prepare("UPDATE rentals SET status='returned',returned_at=NOW(),fine=? WHERE id=?")->execute([$fine,$id]);$pdo->prepare("UPDATE books SET status='available' WHERE id=?")->execute([$r['book_id']]);log_activity('return','rental',$id);$pdo->commit();flash($fine>0?'คืนหนังสือสำเร็จ ค่าปรับ '.format_money($fine).' บาท':'คืนหนังสือสำเร็จ ไม่มีค่าปรับ');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('admin/returns.php');

